/*
 * Ionbit UI — Design Tokens
 *
 * Layered as:
 *   1. :root / .dark — raw semantic variable values (themeable by consumers)
 *   2. @theme inline — Tailwind v4 theme mapping (utilities resolve to the
 *      variables above)
 *
 * Components reference semantic utilities only (bg-surface, text-foreground,
 * border-border, etc.). Retheming = overriding the variables in :root / .dark.
 *
 * The default theme is dark, technical, and restrained. Not neon cyberpunk.
 */

/* ---------------------------------------------------------------------------
 * 1. Raw semantic token values
 * --------------------------------------------------------------------------- */

:root {
  /* The default theme is dark. These values ARE the dark theme. */
  color-scheme: dark;

  /* Surfaces — subtle brightness steps, not flat black. */
  --background: oklch(0.16 0.012 250); /* deep neutral, faintly cool */
  --surface: oklch(0.19 0.013 250);
  --surface-elevated: oklch(0.22 0.014 250);
  --surface-hover: oklch(0.235 0.015 250);

  /* Foreground — high but not pure-white contrast. */
  --foreground: oklch(0.96 0.005 250);
  --foreground-muted: oklch(0.68 0.012 250);
  --foreground-subtle: oklch(0.52 0.012 250);

  /* Borders — barely visible at rest, stronger on interaction. */
  --border: oklch(1 0 0 / 0.08);
  --border-strong: oklch(1 0 0 / 0.14);
  --border-accent: oklch(0.77 0.17 241 / 0.5);
  --border-error: oklch(0.62 0.24 5 / 0.5);
  --border-success: oklch(0.78 0.15 155 / 0.5);
  --border-warning: oklch(0.82 0.15 80 / 0.5);
  --border-info: oklch(0.82 0.14 230 / 0.5);

  /* Accent — deep blue family. Configurable. */
  --accent: oklch(0.77 0.17 241);
  --accent-hover: oklch(0.81 0.18 241);
  --accent-muted: oklch(0.77 0.17 241 / 0.16);
  --accent-subtle: oklch(0.77 0.17 241 / 0.08);
  --accent-foreground: oklch(0.1 0.02 241);

  /* Semantic status — restrained, not neon. */
  --success: oklch(0.78 0.15 155);
  --success-hover: oklch(0.72 0.14 155);
  --success-muted: oklch(0.78 0.15 155 / 0.16);
  --success-subtle: oklch(0.78 0.15 155 / 0.08);
  --success-foreground: oklch(0.1 0.03 155);
  --warning: oklch(0.82 0.15 80);
  --warning-hover: oklch(0.76 0.14 80);
  --warning-muted: oklch(0.82 0.15 80 / 0.16);
  --warning-subtle: oklch(0.82 0.15 80 / 0.08);
  --warning-foreground: oklch(0.1 0.03 80);
  --error: oklch(0.62 0.24 5);
  --error-hover: oklch(0.56 0.22 5);
  --error-muted: oklch(0.62 0.24 5 / 0.16);
  --error-subtle: oklch(0.62 0.24 5 / 0.08);
  --error-foreground: oklch(0.1 0.04 5);
  --info: oklch(0.82 0.14 230);
  --info-hover: oklch(0.76 0.13 230);
  --info-muted: oklch(0.82 0.14 230 / 0.16);
  --info-subtle: oklch(0.82 0.14 230 / 0.08);
  --info-foreground: oklch(0.1 0.03 230);

  /* Focus ring — accent-tinted, visible but not loud. */
  --ring: oklch(0.81 0.18 241 / 0.55);

  /* Typography */
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  --font-mono:
    ui-monospace, "SF Mono", "JetBrains Mono", "Fira Code", Menlo, Consolas,
    monospace;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;

  --leading-tight: 1.2;
  --leading-normal: 1.5;
  --leading-relaxed: 1.65;

  --tracking-tight: -0.01em;
  --tracking-normal: 0;
  --tracking-wide: 0.02em;

  --weight-normal: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;

  /* Spacing scale — 4px base. */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;

  /* Radius — controlled, not bubbly. */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-full: 9999px;

  /* Shadows — subtle, used for depth, not drama. */
  --shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 0.2);
  --shadow-sm:
    0 2px 4px -1px oklch(0 0 0 / 0.25), 0 1px 2px -1px oklch(0 0 0 / 0.2);
  --shadow-md:
    0 4px 8px -2px oklch(0 0 0 / 0.3), 0 2px 4px -2px oklch(0 0 0 / 0.25);
  --shadow-lg:
    0 12px 24px -8px oklch(0 0 0 / 0.4), 0 4px 8px -4px oklch(0 0 0 / 0.3);
  --shadow-glow:
    0 0 0 1px var(--border-accent),
    0 0 16px -4px color-mix(in oklab, var(--accent) 40%, transparent);
  --shadow-glow-error:
    0 0 0 1px var(--border-error),
    0 0 16px -4px color-mix(in oklab, var(--error) 40%, transparent);
  --shadow-focus: 0 0 0 2px var(--ring), 0 0 16px -4px var(--accent);
  --shadow-focus-error: 0 0 0 2px var(--error), 0 0 16px -4px var(--error);

  /* Motion — durations (ms) and easings. */
  --duration-fast: 140ms;
  --duration-normal: 220ms;
  --duration-slow: 420ms;
  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-emphasized: cubic-bezier(0.3, 0, 0, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);

  /* Effect intensities — 0..1 multipliers. */
  --spotlight-intensity: 0.4;
  --magnetic-intensity: 0.25;
}

/* ---------------------------------------------------------------------------
 * Light theme override — architecture supports it; not the priority.
 * --------------------------------------------------------------------------- */

.light {
  color-scheme: light;

  --background: oklch(0.99 0.002 250);
  --surface: oklch(0.98 0.003 250);
  --surface-elevated: oklch(1 0 0);
  --surface-hover: oklch(0.95 0.005 250);

  --foreground: oklch(0.18 0.012 250);
  --foreground-muted: oklch(0.42 0.012 250);
  --foreground-subtle: oklch(0.58 0.012 250);

  --border: oklch(0 0 0 / 0.1);
  --border-strong: oklch(0 0 0 / 0.16);
  --border-accent: oklch(0.55 0.2 241 / 0.5);
  --border-error: oklch(0.52 0.24 5 / 0.5);
  --border-success: oklch(0.58 0.16 155 / 0.5);
  --border-warning: oklch(0.62 0.17 80 / 0.5);
  --border-info: oklch(0.58 0.16 238 / 0.5);

  --accent: oklch(0.55 0.2 241);
  --accent-hover: oklch(0.49 0.21 241);
  --accent-muted: oklch(0.55 0.2 241 / 0.14);
  --accent-subtle: oklch(0.55 0.2 241 / 0.07);
  --accent-foreground: oklch(0.99 0 0);

  --success: oklch(0.56 0.16 155);
  --success-hover: oklch(0.5 0.15 155);
  --success-muted: oklch(0.56 0.16 155 / 0.14);
  --success-subtle: oklch(0.56 0.16 155 / 0.07);
  --success-foreground: oklch(0.99 0 0);
  --warning: oklch(0.6 0.17 80);
  --warning-hover: oklch(0.54 0.16 80);
  --warning-muted: oklch(0.6 0.17 80 / 0.14);
  --warning-subtle: oklch(0.6 0.17 80 / 0.07);
  --warning-foreground: oklch(0.99 0 0);
  --error: oklch(0.5 0.24 5);
  --error-hover: oklch(0.44 0.22 5);
  --error-muted: oklch(0.5 0.24 5 / 0.14);
  --error-subtle: oklch(0.5 0.24 5 / 0.07);
  --error-foreground: oklch(0.99 0 0);
  --info: oklch(0.56 0.16 238);
  --info-hover: oklch(0.5 0.15 238);
  --info-muted: oklch(0.56 0.16 238 / 0.14);
  --info-subtle: oklch(0.56 0.16 238 / 0.07);
  --info-foreground: oklch(0.99 0 0);

  --ring: oklch(0.59 0.19 241 / 0.5);

  --shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 0.06);
  --shadow-sm:
    0 2px 4px -1px oklch(0 0 0 / 0.08), 0 1px 2px -1px oklch(0 0 0 / 0.06);
  --shadow-md:
    0 4px 8px -2px oklch(0 0 0 / 0.1), 0 2px 4px -2px oklch(0 0 0 / 0.08);
  --shadow-lg:
    0 12px 24px -8px oklch(0 0 0 / 0.12), 0 4px 8px -4px oklch(0 0 0 / 0.1);
  --shadow-glow:
    0 0 0 1px var(--border-accent),
    0 0 16px -4px color-mix(in oklab, var(--accent) 40%, transparent);
  --shadow-glow-error:
    0 0 0 1px var(--border-error),
    0 0 16px -4px color-mix(in oklab, var(--error) 40%, transparent);
  --shadow-focus: 0 0 0 2px var(--ring), 0 0 16px -4px var(--accent);
  --shadow-focus-error: 0 0 0 2px var(--error), 0 0 16px -4px var(--error);
}

/* ---------------------------------------------------------------------------
 * 2. Tailwind v4 theme mapping
 *    Utilities like bg-surface, text-foreground, border-border resolve to
 *    the variables above. Consumers override the variables, not the utilities.
 * --------------------------------------------------------------------------- */

@theme inline {
  /* Colors */
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-surface-elevated: var(--surface-elevated);
  --color-surface-hover: var(--surface-hover);
  --color-foreground: var(--foreground);
  --color-foreground-muted: var(--foreground-muted);
  --color-foreground-subtle: var(--foreground-subtle);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-border-accent: var(--border-accent);
  --color-border-error: var(--border-error);
  --color-border-success: var(--border-success);
  --color-border-warning: var(--border-warning);
  --color-border-info: var(--border-info);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-muted: var(--accent-muted);
  --color-accent-subtle: var(--accent-subtle);
  --color-accent-foreground: var(--accent-foreground);
  --color-success: var(--success);
  --color-success-hover: var(--success-hover);
  --color-success-muted: var(--success-muted);
  --color-success-subtle: var(--success-subtle);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-hover: var(--warning-hover);
  --color-warning-muted: var(--warning-muted);
  --color-warning-subtle: var(--warning-subtle);
  --color-warning-foreground: var(--warning-foreground);
  --color-error: var(--error);
  --color-error-hover: var(--error-hover);
  --color-error-muted: var(--error-muted);
  --color-error-subtle: var(--error-subtle);
  --color-error-foreground: var(--error-foreground);
  --color-info: var(--info);
  --color-info-hover: var(--info-hover);
  --color-info-muted: var(--info-muted);
  --color-info-subtle: var(--info-subtle);
  --color-info-foreground: var(--info-foreground);
  --color-ring: var(--ring);

  /* Fonts */
  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  /* Radius */
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-full: var(--radius-full);

  /* Shadows */
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-glow: var(--shadow-glow);
  --shadow-glow-error: var(--shadow-glow-error);
  --shadow-focus: var(--shadow-focus);
  --shadow-focus-error: var(--shadow-focus-error);

  /* Motion durations + easings (Tailwind v4 exposes them as utilities) */
  --duration-fast: var(--duration-fast);
  --duration-normal: var(--duration-normal);
  --duration-slow: var(--duration-slow);
  --ease-standard: var(--ease-standard);
  --ease-emphasized: var(--ease-emphasized);
  --ease-exit: var(--ease-exit);

  /* Accordion expand/collapse — syncs with Radix's --radix-accordion-content-height */
  --animate-accordion-down: accordion-down var(--duration-normal)
    var(--ease-standard);
  --animate-accordion-up: accordion-up var(--duration-normal)
    var(--ease-standard);

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

/*
 * Ionbit UI — Base layer
 *
 * Minimal reset-adjacent defaults + reduced-motion policy.
 * Import once at the application root, after tokens.css.
 */

@layer base {
  * {
    border-color: var(--border);
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    line-height: var(--leading-normal);
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  /* Reduced-motion policy: disable all animations and transitions by default.
     Components and primitives must opt in via .motion-safe for animations
     that are safe to keep (functional, non-distracting state changes). */
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.001ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.001ms !important;
      scroll-behavior: auto !important;
    }
  }
}

/* Opt-in escape hatch for animations that are safe under reduced motion. */
@media (prefers-reduced-motion: reduce) {
  .motion-safe\:animate,
  .motion-safe\:transition {
    animation-duration: var(--duration-fast) !important;
    transition-duration: var(--duration-fast) !important;
  }
}

/*
 * Ionbit UI — CSS Utilities
 *
 * Scroll-fade and shimmer utilities, inspired by shadcn.
 * Import in your global CSS after Tailwind:
 *   @import "tailwindcss";
 *   @import "ionbit-ui/tailwind.css";
 *
 * These use Tailwind v4 at-rules (@utility, @theme inline, @variant)
 * and must be processed by the Tailwind engine, not lightningcss.
 */

/* no-scrollbar */
@utility no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

/* ─── scroll-fade ─── */
@property --scroll-fade-t {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}
@property --scroll-fade-b {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}
@property --scroll-fade-s {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}
@property --scroll-fade-e {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}
@property --scroll-fade-mask {
  syntax: "*";
  inherits: false;
}

@theme inline {
  @keyframes scroll-fade-reveal-t {
    from {
      --scroll-fade-t: 0px;
    }
    to {
      --scroll-fade-t: var(
        --_scroll-fade-size-t,
        var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
      );
    }
  }
  @keyframes scroll-fade-reveal-b {
    from {
      --scroll-fade-b: var(
        --_scroll-fade-size-b,
        var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
      );
    }
    to {
      --scroll-fade-b: 0px;
    }
  }
  @keyframes scroll-fade-reveal-s {
    from {
      --scroll-fade-s: 0px;
    }
    to {
      --scroll-fade-s: var(
        --_scroll-fade-size-s,
        var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
      );
    }
  }
  @keyframes scroll-fade-reveal-e {
    from {
      --scroll-fade-e: var(
        --_scroll-fade-size-e,
        var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
      );
    }
    to {
      --scroll-fade-e: 0px;
    }
  }
}

@utility scroll-fade {
  --_scroll-fade-size-t: var(
    --scroll-fade-t-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --_scroll-fade-size-b: var(
    --scroll-fade-b-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --scroll-fade-block: linear-gradient(
    to bottom,
    transparent 0,
    #000 var(--scroll-fade-t, 0px),
    #000 calc(100% - var(--scroll-fade-b, 0px)),
    transparent 100%
  );
  -webkit-mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
  mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;

  @supports (animation-timeline: scroll()) {
    animation:
      scroll-fade-reveal-t 1ms ease-in-out,
      scroll-fade-reveal-b 1ms ease-in-out;
    animation-timeline: scroll(self y), scroll(self y);
    animation-range:
      0 var(--scroll-fade-reveal, calc(var(--spacing) * 24)),
      calc(100% - var(--scroll-fade-reveal, calc(var(--spacing) * 24))) 100%;
    animation-fill-mode: both;
  }

  @supports not (animation-timeline: scroll()) {
    --scroll-fade-t: var(--_scroll-fade-size-t);
    --scroll-fade-b: var(--_scroll-fade-size-b);
  }
}

@utility scroll-fade-y {
  --_scroll-fade-size-t: var(
    --scroll-fade-t-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --_scroll-fade-size-b: var(
    --scroll-fade-b-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --scroll-fade-block: linear-gradient(
    to bottom,
    transparent 0,
    #000 var(--scroll-fade-t, 0px),
    #000 calc(100% - var(--scroll-fade-b, 0px)),
    transparent 100%
  );
  -webkit-mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
  mask-image: var(--scroll-fade-mask, var(--scroll-fade-block));
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;

  @supports (animation-timeline: scroll()) {
    animation:
      scroll-fade-reveal-t 1ms ease-in-out,
      scroll-fade-reveal-b 1ms ease-in-out;
    animation-timeline: scroll(self y), scroll(self y);
    animation-range:
      0 var(--scroll-fade-reveal, calc(var(--spacing) * 24)),
      calc(100% - var(--scroll-fade-reveal, calc(var(--spacing) * 24))) 100%;
    animation-fill-mode: both;
  }

  @supports not (animation-timeline: scroll()) {
    --scroll-fade-t: var(--_scroll-fade-size-t);
    --scroll-fade-b: var(--_scroll-fade-size-b);
  }
}

@utility scroll-fade-x {
  --_scroll-fade-size-s: var(
    --scroll-fade-s-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --_scroll-fade-size-e: var(
    --scroll-fade-e-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --scroll-fade-inline: linear-gradient(
    to right,
    transparent 0,
    #000 var(--scroll-fade-s, 0px),
    #000 calc(100% - var(--scroll-fade-e, 0px)),
    transparent 100%
  );
  &:where([dir="rtl"], [dir="rtl"] *) {
    --scroll-fade-inline: linear-gradient(
      to left,
      transparent 0,
      #000 var(--scroll-fade-s, 0px),
      #000 calc(100% - var(--scroll-fade-e, 0px)),
      transparent 100%
    );
  }
  -webkit-mask-image: var(--scroll-fade-mask, var(--scroll-fade-inline));
  mask-image: var(--scroll-fade-mask, var(--scroll-fade-inline));
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;

  @supports (animation-timeline: scroll()) {
    animation:
      scroll-fade-reveal-s 1ms ease-in-out,
      scroll-fade-reveal-e 1ms ease-in-out;
    animation-timeline: scroll(self inline), scroll(self inline);
    animation-range:
      0 var(--scroll-fade-reveal, calc(var(--spacing) * 24)),
      calc(100% - var(--scroll-fade-reveal, calc(var(--spacing) * 24))) 100%;
    animation-fill-mode: both;
  }

  @supports not (animation-timeline: scroll()) {
    --scroll-fade-s: var(--_scroll-fade-size-s);
    --scroll-fade-e: var(--_scroll-fade-size-e);
  }
}

@utility scroll-fade-t {
  --_scroll-fade-size-t: var(
    --scroll-fade-t-size,
    var(--scroll-fade-size, min(12%, calc(var(--spacing) * 10)))
  );
  --scroll-fade-mask: linear-gradient(
    to bottom,
    transparent 0,
    #000 var(--scroll-fade-t, 0px),
    #000 100%
  );
  -webkit-mask-image: var(--scroll-fade-mask);
  mask-image: var(--scroll-fade-mask);
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;

  @supports (animation-timeline: scroll()) {
    animation: scroll-fade-reveal-t 1ms ease-in-out;
    animation-timeline: scroll(self y);
    animation-range: 0 var(--scroll-fade-reveal, calc(var(--spacing) * 24));
    animation-fill-mode: both;
  }

  @supports not (animation-timeline: scroll()) {
    --scroll-fade-t: var(--_scroll-fade-size-t);
  }
